// fleet.js — render status/fleet.json + status/fleet_history.jsonl into the
// fleet health board. Zero-build: plain DOM over the JSON generated by
// src/fleet_refresh.oo. Sparkline cells come from the last 24 history ticks.
(function () {
  'use strict';

  var grid = document.getElementById('fleet-grid');
  var stamp = document.getElementById('fleet-stamp');
  var alertsBox = document.getElementById('fleet-alerts');
  var reposWrap = document.getElementById('fleet-repos-wrap');
  var sigWrap = document.getElementById('fleet-signals-wrap');
  if (!grid || !stamp) return;

  var SEV_CLS = ['quota-state-ok', 'quota-state-warn', 'quota-state-warn', 'quota-state-bad'];
  var SEV_LBL = ['ok', 'drift', 'attention', 'breach'];

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  }

  function row(label, value, cls) {
    var r = el('div', 'quota-row');
    r.appendChild(el('span', null, label));
    r.appendChild(el('b', cls || null, value));
    return r;
  }

  function card(name, src, rows) {
    var c = el('div', 'quota-card');
    c.appendChild(el('h3', null, name));
    if (src) c.appendChild(el('span', 'quota-src', src));
    rows.forEach(function (r) { c.appendChild(r); });
    return c;
  }

  function sevCls(n) { return SEV_CLS[n] || 'quota-state-bad'; }

  var history = [];
  function sevSeries(name) {
    return history.slice(-24).map(function (h) {
      var m = h.repo || {};
      return (name in m) ? m[name] : -1;
    });
  }

  function spark(name) {
    var box = el('span');
    sevSeries(name).forEach(function (s) {
      box.appendChild(el('span', s < 0 ? 'fk-tick fk-sx' : 'fk-tick fk-s' + s));
    });
    return box;
  }

  function render(d) {
    stamp.textContent = 'tick sig ' + (d.state_sig || '?') +
      ' · generated_at ' + (d.generated_at || 'unknown') +
      ' · state ' + (d.state_file || '?');
    var s = d.summary || {};
    var al = d.alerts || [];
    if (al.length) {
      var box = el('div', 'fk-alert');
      box.textContent = 'ALERT SPOOL — ' + al.length + ' live: ' + al.join(', ');
      alertsBox.appendChild(box);
    }

    grid.appendChild(card('sweep', 'CLEAN/DIRTY verdicts', [
      row('repos swept', s.repos_total != null ? s.repos_total : '—'),
      row('clean', s.clean != null ? s.clean : '—', 'quota-state-ok'),
      row('dirty', s.dirty != null ? s.dirty : '—', s.dirty ? 'quota-state-warn' : 'quota-state-ok'),
      row('errors', s.err != null ? s.err : '—', s.err ? 'quota-state-bad' : 'quota-state-ok'),
      row('locked', s.locked != null ? s.locked : '—')
    ]));
    grid.appendChild(card('reconcile', 'ff-only, gated', [
      row('repos reconciled', s.recon_total != null ? s.recon_total : '—'),
      row('state seal', s.seal || '—')
    ]));
    grid.appendChild(card('workspaces', 'ACTIVE-WS ledgers', [
      row('workspaces', s.ws_total != null ? s.ws_total : '—'),
      row('active', s.ws_active != null ? s.ws_active : '—')
    ]));

    var repos = d.repos || [];
    if (reposWrap) {
      reposWrap.textContent = '';
      var tbl = el('table', 'quota-panes');
      var head = el('tr');
      ['repo', 'sweep', 'recon', 'severity', 'last 24 ticks'].forEach(function (h) {
        head.appendChild(el('th', null, h));
      });
      tbl.appendChild(head);
      repos.forEach(function (r) {
        var tr = el('tr');
        tr.appendChild(el('td', null, r.name));
        tr.appendChild(el('td', sevCls(r.state === 'CLEAN' ? 0 : 2), r.state));
        tr.appendChild(el('td', null, r.recon));
        tr.appendChild(el('td', sevCls(r.sev), SEV_LBL[r.sev] || '?'));
        var td = el('td'); td.appendChild(spark(r.name)); tr.appendChild(td);
        tbl.appendChild(tr);
      });
      reposWrap.appendChild(tbl);
    }

    if (sigWrap) {
      sigWrap.textContent = '';
      var qt = el('table', 'quota-panes');
      var qh = el('tr');
      ['agent', 'state', 'used', 'remaining'].forEach(function (h) { qh.appendChild(el('th', null, h)); });
      qt.appendChild(qh);
      (d.quota || []).forEach(function (q) {
        var tr = el('tr');
        tr.appendChild(el('td', null, q.agent));
        tr.appendChild(el('td', q.state === 'OK' ? 'quota-state-ok' : q.state === 'UNKNOWN' ? null : 'quota-state-bad', q.state));
        tr.appendChild(el('td', null, q.used < 0 ? '—' : String(q.used)));
        tr.appendChild(el('td', null, q.rem < 0 ? '—' : String(q.rem)));
        qt.appendChild(tr);
      });
      sigWrap.appendChild(qt);
      var ws = d.workspaces || [];
      if (ws.length) {
        var p = el('p', 'fk-mono');
        p.textContent = ws.map(function (w) {
          return w.ws + ' blocked=' + w.blocked + ' working=' + w.working + ' idle=' + w.idle;
        }).join('  ·  ');
        sigWrap.appendChild(p);
      }
      (d.health_forge || []).forEach(function (hf) {
        sigWrap.appendChild(el('p', 'fk-mono', hf.src + '  ' + hf.line));
      });
    }
  }

  fetch('fleet_history.jsonl', { cache: 'no-store' })
    .then(function (r) { return r.ok ? r.text() : Promise.reject(r.status); })
    .then(function (t) {
      t.split('\n').forEach(function (ln) {
        var s = ln.trim();
        if (s) { try { history.push(JSON.parse(s)); } catch (e) { /* skip */ } }
      });
    })
    .catch(function () { /* sparklines render gaps */ })
    .then(function () {
      return fetch('fleet.json', { cache: 'no-store' });
    })
    .then(function (r) { return r.ok ? r.json() : Promise.reject(r.status); })
    .then(render)
    .catch(function () {
      stamp.textContent = 'fleet.json unavailable — run the .oo refresh driver (see below).';
      grid.appendChild(el('p', 'quota-note', 'No data file found. The board renders status/fleet.json generated by src/fleet_refresh.oo.'));
    });
})();
